
-- Synthetic demonstration records for isolated local/staging environments only.
-- Every customer-visible title and reference is labelled DEMO so this data cannot
-- be mistaken for an authorised Hilltop listing.
on conflict do nothing;
on conflict(slug) do nothing;

on conflict(reference) do nothing;

select property.id, amenity.id from public.properties property cross join public.amenities amenity
where property.reference like 'DEMO-%' and amenity.slug in ('security','parking','backup-power')
on conflict do nothing;

select 'property',id,'Demo Customer','demo-customer@example.invalid','+260 000 000 010','Synthetic enquiry created only for local workflow testing.','new',true,'10000000-0000-4000-8000-000000000001','demo-seed'
from public.properties where reference='DEMO-SALE-001'
on conflict(idempotency_key) do nothing;
select id,'Demo Customer','demo-customer@example.invalid','+260 000 000 010','physical',now()+interval '3 days','requested',true,'20000000-0000-4000-8000-000000000001','Synthetic viewing request for local testing.',tstzrange(now()+interval '3 days',now()+interval '3 days 1 hour','[)')
from public.properties where reference='DEMO-SALE-001'
on conflict(idempotency_key) do nothing;
