values
('DEMO-SALE-001','demo-kabulonga-family-house','[DEMO] Kabulonga family house','Synthetic four-bedroom house used for local UI testing.','Demonstration listing only. A spacious family layout with garden, parking and flexible living areas.','sale','published',(select id from public.property_categories where slug='residential'),(select id from public.property_types where slug='house'),(select id from public.locations where slug='kabulonga'),(select id from public.agents where slug='demo-advisor-lusaka'),4850000,'once','ZMW',4,3,2,1200,'m²',310,-15.4145,28.3452,'Demonstration address, Kabulonga',true,true,now()-interval '2 days'),
('DEMO-RENT-001','demo-ibex-hill-rental','[DEMO] Ibex Hill rental home','Synthetic rental used for local UI testing.','Demonstration listing only. A secure rental home with three bedrooms and backup power.','rent','published',(select id from public.property_categories where slug='residential'),(select id from public.property_types where slug='house'),(select id from public.locations where slug='ibex-hill'),(select id from public.agents where slug='demo-advisor-lusaka'),28000,'month','ZMW',3,2,2,650,'m²',220,-15.4470,28.4020,'Demonstration address, Ibex Hill',true,true,now()-interval '1 day'),
('DEMO-APT-001','demo-foxdale-apartment','[DEMO] Foxdale apartment','Synthetic apartment used for local UI testing.','Demonstration listing only. A compact apartment near everyday services.','sale','published',(select id from public.property_categories where slug='residential'),(select id from public.property_types where slug='apartment'),(select id from public.locations where slug='foxdale'),(select id from public.agents where slug='demo-advisor-lusaka'),1750000,'once','ZMW',2,2,1,null,null,115,-15.3550,28.3100,'Demonstration address, Foxdale',false,true,now()-interval '4 days'),
('DEMO-PLOT-001','demo-chongwe-residential-plot','[DEMO] Chongwe residential plot','Synthetic serviced plot used for local UI testing.','Demonstration listing only. A residential plot with road frontage and electricity nearby.','sale','published',(select id from public.property_categories where slug='land'),(select id from public.property_types where slug='plot'),(select id from public.locations where slug='chongwe'),(select id from public.agents where slug='demo-advisor-lusaka'),620000,'once','ZMW',0,0,0,1800,'m²',null,-15.3290,28.6820,'Demonstration location, Chongwe',false,true,now()-interval '7 days'),
('DEMO-OFFICE-001','demo-makeni-office','[DEMO] Makeni commercial office','Synthetic office property used for local UI testing.','Demonstration listing only. Flexible office accommodation with customer parking.','rent','published',(select id from public.property_categories where slug='commercial'),(select id from public.property_types where slug='office'),(select id from public.locations where slug='makeni'),(select id from public.agents where slug='demo-advisor-lusaka'),45000,'month','ZMW',0,2,8,900,'m²',420,-15.5060,28.2390,'Demonstration address, Makeni',false,true,now()-interval '3 days'),
('DEMO-FARM-001','demo-chongwe-farm','[DEMO] Chongwe agricultural holding','Synthetic farm used for local UI testing.','Demonstration listing only. Agricultural land with a residence and utility buildings.','investment','published',(select id from public.property_categories where slug='land'),(select id from public.property_types where slug='farm'),(select id from public.locations where slug='chongwe'),(select id from public.agents where slug='demo-advisor-lusaka'),9200000,'once','ZMW',3,2,4,42,'hectares',280,-15.2810,28.7510,'Approximate demonstration location, Chongwe',true,true,now()-interval '6 days'),
('DEMO-ESTATE-001','demo-livingstone-estate','[DEMO] Livingstone private estate','Synthetic luxury estate used for local UI testing.','Demonstration listing only. A large private estate configured to test premium property presentation.','investment','published',(select id from public.property_categories where slug='residential'),(select id from public.property_types where slug='estate'),(select id from public.locations where slug='livingstone'),(select id from public.agents where slug='demo-advisor-livingstone'),null,'once','ZMW',8,7,6,148,'acres',1250,-17.8410,25.8540,'Approximate demonstration location, Livingstone',true,true,now()-interval '5 days'),
